// Prompt library for the Studio's "Prompts" tab.
// - prompts/library.json is generated by scripts/build-prompts.mjs from the markdown collections (rebuild any time).
// - prompts/meus.json is Erick's own data: favourites, copy/use counts, his own prompts and the example file chosen
//   for any prompt. The build script never touches it, so rebuilding the library never loses any of that.
import { randomBytes } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, statSync } from "node:fs";
import type { IncomingMessage, ServerResponse } from "node:http";
import { join, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { OUTPUT_DIR, bodyJson, sendJson, str, writeJsonSafe } from "./extras-http.js";

export const PROMPTS_DIR = process.env.FLOW_MCP_PROMPTS ?? fileURLToPath(new URL("../prompts/", import.meta.url));
const LIBRARY = join(PROMPTS_DIR, "library.json");
const MINE = join(PROMPTS_DIR, "meus.json");
const MEDIA = /\.(mp4|webm|mov|gif|jpe?g|png|webp)$/i;

interface Part { label?: string; kind: string; text: string }
interface Item {
  id: string; title: string; category: string; source: string; link?: string; orientation: string; kind: string;
  popularity?: number; date?: string; order?: number; parts: Part[];
  example?: { url?: string; path?: string; type: string };
}
interface Own { id: string; title: string; text: string; kind: string; orientation: string; created: string; updated: string }
interface UserData {
  version: 1;
  favorites: string[];
  counts: Record<string, { copies?: number; uses?: number }>;
  examples: Record<string, string>;
  mine: Own[];
}

let cache: { mtime: number; lib: { built?: string; categories?: string[]; items: Item[] } } | null = null;
function library() {
  if (!existsSync(LIBRARY)) return { built: undefined, categories: [], items: [] as Item[] };
  const mtime = statSync(LIBRARY).mtimeMs;
  if (cache?.mtime !== mtime) cache = { mtime, lib: JSON.parse(readFileSync(LIBRARY, "utf8")) };
  return cache.lib;
}
function userData(): UserData {
  const empty: UserData = { version: 1, favorites: [], counts: {}, examples: {}, mine: [] };
  if (!existsSync(MINE)) return empty;
  return { ...empty, ...JSON.parse(readFileSync(MINE, "utf8")) };
}
function saveUser(d: UserData) {
  mkdirSync(PROMPTS_DIR, { recursive: true });
  writeJsonSafe(MINE, d);
}

const inOutputs = (p: string) => resolve(p).startsWith(resolve(OUTPUT_DIR) + sep);
const exampleOf = (path: string) => ({ path, type: /\.(mp4|webm|mov)$/i.test(path) ? "video" : "image" });

function merged() {
  const lib = library(), u = userData();
  const fav = new Set(u.favorites);
  const own: Item[] = u.mine.map((m) => ({
    id: m.id, title: m.title, category: "Meus", source: "Você", orientation: m.orientation, kind: m.kind,
    date: m.updated || m.created, parts: [{ kind: m.kind === "imagem" ? "image" : "video", text: m.text }],
  }));
  const items = [...own, ...lib.items].map((it) => {
    const mine = u.examples[it.id];
    // An example file that was moved to the bin since is simply not shown.
    const local = mine && existsSync(mine) ? exampleOf(mine) : undefined;
    return { ...it, favorite: fav.has(it.id), copies: u.counts[it.id]?.copies ?? 0, uses: u.counts[it.id]?.uses ?? 0, example: local ?? it.example, library_example: it.example, own: it.category === "Meus" };
  });
  return { built: lib.built, categories: lib.categories ?? [], items };
}

// Answers /api/prompts and /api/prompts/<action>; returns false for any other path.
export async function handlePrompts(req: IncomingMessage, res: ServerResponse, url: URL): Promise<boolean> {
  const m = url.pathname.match(/^\/api\/prompts(?:\/(\w+))?$/);
  if (!m) return false;
  const action = m[1] ?? "list";
  if (action === "list") {
    sendJson(res, 200, merged());
    return true;
  }
  if (req.method !== "POST") return false;
  const b = await bodyJson(req);
  const id = str(b.id, 80);
  const u = userData();
  const known = () => Boolean(id && (u.mine.some((x) => x.id === id) || library().items.some((x) => x.id === id)));

  if (action === "favorite") {
    if (!known()) throw new Error("Prompt não encontrado.");
    const on = typeof b.on === "boolean" ? b.on : !u.favorites.includes(id!);
    u.favorites = u.favorites.filter((x) => x !== id);
    if (on) u.favorites.push(id!);
    saveUser(u);
    sendJson(res, 200, { id, favorite: on });
    return true;
  }
  if (action === "count") {
    if (!known()) throw new Error("Prompt não encontrado.");
    const what = b.what === "use" ? "uses" : "copies";
    const c = (u.counts[id!] ??= {});
    c[what] = (c[what] ?? 0) + 1;
    saveUser(u);
    sendJson(res, 200, { id, copies: c.copies ?? 0, uses: c.uses ?? 0 });
    return true;
  }
  if (action === "save") {
    const title = str(b.title, 200)?.trim(), text = str(b.text)?.trim();
    if (!title || !text) throw new Error("Dê um título e escreva o prompt.");
    const kind = b.kind === "imagem" ? "imagem" : b.kind === "vídeo com fala" ? "vídeo com fala" : "movimento";
    const orientation = b.orientation === "horizontal" ? "horizontal" : b.orientation === "unknown" ? "unknown" : "vertical";
    const now = new Date().toISOString();
    let own = id ? u.mine.find((x) => x.id === id) : undefined;
    if (id && !own) throw new Error("Só dá para editar os seus próprios prompts.");
    if (own) Object.assign(own, { title, text, kind, orientation, updated: now });
    else u.mine.unshift((own = { id: `meu-${randomBytes(4).toString("hex")}`, title, text, kind, orientation, created: now, updated: now }));
    saveUser(u);
    sendJson(res, 200, { id: own.id });
    return true;
  }
  if (action === "delete") {
    if (!id || !u.mine.some((x) => x.id === id)) throw new Error("Só dá para apagar os seus próprios prompts.");
    u.mine = u.mine.filter((x) => x.id !== id);
    u.favorites = u.favorites.filter((x) => x !== id);
    delete u.counts[id];
    delete u.examples[id];
    saveUser(u);
    sendJson(res, 200, { id, deleted: true });
    return true;
  }
  if (action === "example") {
    if (!known()) throw new Error("Prompt não encontrado.");
    const path = str(b.path, 4096);
    if (path) {
      if (!inOutputs(path) || !MEDIA.test(path) || !existsSync(path)) throw new Error("Escolha um vídeo ou imagem da Galeria.");
      u.examples[id!] = resolve(path);
    } else delete u.examples[id!];
    saveUser(u);
    sendJson(res, 200, { id, example: path ? exampleOf(resolve(path)) : null });
    return true;
  }
  return false;
}
